package main

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// completionsDir holds shell completion scripts generated by apply. ~/.bashrc
// and ~/.zshrc source them at startup.
func completionsDir(homeDir string) string {
	return filepath.Join(homeDir, ".cache", "dotfiles", "completions")
}

// completionTimeout bounds `kubectl completion`; a variable for tests.
var completionTimeout = 10 * time.Second

// completionMarker is what a real completion script defines; output without
// it (a wrapper's notice, ...) is not cached, or every shell would source it.
var completionMarker = map[string]string{
	"bash": "__start_kubectl",
	"zsh":  "_kubectl",
}

// completionShells are the shells kubectl completion is cached for.
func completionShells(shell string) []string {
	if shell == "zsh" {
		return []string{"bash", "zsh"}
	}
	return []string{"bash"}
}

// kubectlCompletion runs `kubectl completion <sh>` with a timeout, and
// without mise auto-installing a missing kubectl behind apply's back.
func kubectlCompletion(sh string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(context.Background(), completionTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "kubectl", "completion", sh)
	// MISE_AUTO_INSTALL=0 stops a mise shim from installing a missing pinned
	// version (MISE_EXEC_AUTO_INSTALL alone does not).
	cmd.Env = append(os.Environ(), "MISE_AUTO_INSTALL=0", "MISE_EXEC_AUTO_INSTALL=0", "MISE_NOT_FOUND_AUTO_INSTALL=0")
	// The timeout kills only kubectl itself; if it is a wrapper script, its
	// children keep stdout open. Stop waiting for them, too.
	cmd.WaitDelay = 2 * time.Second
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if ctx.Err() != nil {
		return nil, fmt.Errorf("timed out after %s", completionTimeout)
	}
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			if msg := strings.TrimSpace(stderr.String()); msg != "" {
				return nil, fmt.Errorf("%w: %s", err, msg)
			}
		}
		return nil, err
	}
	if !bytes.Contains(out, []byte(completionMarker[sh])) {
		return nil, fmt.Errorf("output is not a %s completion script (no %s)", sh, completionMarker[sh])
	}
	return out, nil
}

// ensureCompletions caches `kubectl completion <shell>`. Generating it takes
// kubectl ~150ms, sourcing the cached file ~10ms. It is loaded eagerly
// because the `k` alias is completed by __start_kubectl, and bash-completion's
// lazy loader keys on the typed command name, so it never loads kubectl's
// script for `k` (#13). The shells only source the file, never generate it:
// a broken kubectl must not slow down every shell start. Regenerated on every
// apply, so a kubectl upgrade is picked up by the next apply. kubectl itself
// is not a managed tool; without it nothing happens. Failures are warnings: a
// missing completion must not fail apply.
func ensureCompletions(homeDir, shell, command string) {
	if _, err := exec.LookPath("kubectl"); err != nil {
		return
	}
	for _, sh := range completionShells(shell) {
		path := filepath.Join(completionsDir(homeDir), "kubectl."+sh)
		out, err := kubectlCompletion(sh)
		if err != nil {
			fmt.Printf("⚠️ kubectl completion %s: %v\n", sh, err)
			continue
		}
		if command == "diff" {
			if old, err := os.ReadFile(path); err != nil {
				fmt.Printf("+ %s (kubectl completion %s)\n", tildePath(path), sh)
			} else if !bytes.Equal(old, out) {
				fmt.Printf("~ %s (kubectl completion %s changed)\n", tildePath(path), sh)
			}
			continue
		}
		changed, err := writeGenerated(path, out)
		if err != nil {
			fmt.Printf("⚠️ could not write %s: %v\n", path, err)
			continue
		}
		if changed {
			fmt.Printf("✅ Applied %s\n", path)
		} else {
			fmt.Printf("   unchanged %s\n", path)
		}
	}
}

// writeGenerated writes content to path atomically (a failed run never leaves
// a truncated script) and reports whether it changed.
func writeGenerated(path string, content []byte) (bool, error) {
	if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, content) {
		return false, nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return false, err
	}
	if err := writeFileAtomic(path, content, 0644); err != nil {
		return false, err
	}
	return true, nil
}
